export const WAREHOUSE_LAYOUTS: WarehouseLayout[] = [khotp, khotd1, khotd2, hd1, hd2, khopl];

export const getLayoutByMaKho = (maKho?: string): WarehouseLayout | undefined =>
  WAREHOUSE_LAYOUTS.find((l) => l.maKho === maKho);

export const hasWarehouseLayout = (maKho?: string): boolean =>
  WAREHOUSE_LAYOUTS.some((l) => l.maKho === maKho);
